SELECT "nct", "author", "year", "pubmed_id", "trial_name", "trial_phase", "cancer_type", "treatment_regimen", "name_of_ici", "class_of_ici", "type_of_combination", "control_regimen" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%non-small cell lung%' AND "class_of_ici" ILIKE '%PD1%' AND "class_of_ici" ILIKE '%CTLA4%' AND "trial_phase" = 'Phase 3' AND "type_of_combination" ILIKE '%combination%' ORDER BY "year" DESC;